import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

class Solution {
    private static class State {
        TreeNode node;
        int sum;
        State(TreeNode node, int sum) { this.node = node; this.sum = sum; }
    }

    public int maxPathSum(TreeNode root) {
        List<TreeNode> nodes = new ArrayList<>();
        Deque<TreeNode> pending = new ArrayDeque<>();
        pending.push(root);
        while (!pending.isEmpty()) {
            TreeNode node = pending.pop();
            nodes.add(node);
            if (node.left != null) pending.push(node.left);
            if (node.right != null) pending.push(node.right);
        }
        int best = Integer.MIN_VALUE;
        for (TreeNode node : nodes) {
            int left = Math.max(0, bestDown(node.left));
            int right = Math.max(0, bestDown(node.right));
            best = Math.max(best, node.val + left + right);
        }
        return best;
    }

    private int bestDown(TreeNode start) {
        if (start == null) return 0;
        int best = Integer.MIN_VALUE;
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(start, start.val));
        while (!stack.isEmpty()) {
            State state = stack.pop();
            best = Math.max(best, state.sum);
            if (state.node.left != null) stack.push(new State(state.node.left, state.sum + state.node.left.val));
            if (state.node.right != null) stack.push(new State(state.node.right, state.sum + state.node.right.val));
        }
        return best;
    }
}

