import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

class Solution {
    public int maxPathSum(TreeNode root) {
        List<TreeNode> order = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            order.add(node);
            if (node.left != null) stack.push(node.left);
            if (node.right != null) stack.push(node.right);
        }
        Map<TreeNode, Integer> gain = new IdentityHashMap<>();
        int best = Integer.MIN_VALUE;
        for (int index = order.size() - 1; index >= 0; index--) {
            TreeNode node = order.get(index);
            int left = node.left == null ? 0 : Math.max(0, gain.get(node.left));
            int right = node.right == null ? 0 : Math.max(0, gain.get(node.right));
            best = Math.max(best, node.val + left + right);
            gain.put(node, node.val + Math.max(left, right));
        }
        return best;
    }
}
